using System;using System.Data;using System.Data.SqlClient;using System.Reflection;using System.Text;using System.Security.Cryptography;using System.Globalization;
using PharmacyManagement.Infrastructure.SqlServer;

// Actual repository SQL, with each fault injection always rolled back on owned QA.
namespace PharmacyManagement.CoreTests {
internal static class ReturnHistoryUnitSqlTests {
 static string cs;static Guid packageReturn,packageOriginal,packageLine,baseReturn,baseOriginal,baseLine,baseSource;static int passed,failed;
 static MethodInfo query=typeof(SqlCommercialReturnReadRepository).GetMethod("BuildDocumentSql",BindingFlags.Static|BindingFlags.NonPublic);
 internal static int Run(string[] args){try{
  Console.OutputEncoding=Encoding.UTF8;Guid owner;
  if(args.Length!=2||!Guid.TryParseExact(args[1],"N",out owner)||args[0]!="PharmacyUnits_"+args[1]+"_qa")throw new Exception("Exact owned QA required");
  cs="Data Source=.;Initial Catalog="+args[0]+";Integrated Security=True;Pooling=False;Connect Timeout=10;Application Name=Pharmacy return-history rollback matrix";
  using(var c=Open()){
   using(var cmd=new SqlCommand("SELECT CONVERT(nvarchar(100),value) FROM sys.extended_properties WHERE class=0 AND name=N'QaTest.Owner'",c))Require(Convert.ToString(cmd.ExecuteScalar())==args[1],"Owner mismatch");
   using(var cmd=new SqlCommand(@"SELECT TOP(1) h.ReturnId,h.OriginalInvoiceId,l.LineId FROM dbo.CommercialReturnHeadersTb h JOIN dbo.SalesInvoiceLinesTb l ON l.InvoiceId=h.ReturnInvoiceId JOIN dbo.InvoiceUnitSnapshotsTb u ON u.DocumentKind=N'CommercialReturn' AND u.LineKey=CONVERT(nvarchar(100),l.LineId) WHERE LEFT(l.MedName,12)=N'__UNIT_COMM_' AND u.BaseUnitsPerUnit>1 ORDER BY l.LineId",c))using(var r=cmd.ExecuteReader()){Require(r.Read(),"Package fixture absent");packageReturn=r.GetGuid(0);packageOriginal=r.GetGuid(1);packageLine=r.GetGuid(2);}
   using(var cmd=new SqlCommand(@"SELECT TOP(1) h.ReturnId,h.OriginalInvoiceId,l.LineId,b.OriginalLineId FROM dbo.CommercialReturnHeadersTb h JOIN dbo.SalesInvoiceLinesTb l ON l.InvoiceId=h.ReturnInvoiceId JOIN dbo.CommercialReturnUnitSnapshotsTb b ON b.ReturnInvoiceLineId=l.LineId WHERE LEFT(l.MedName,12)=N'__UNIT_COMM_' ORDER BY l.LineId",c))using(var r=cmd.ExecuteReader()){Require(r.Read(),"Base fixture absent");baseReturn=r.GetGuid(0);baseOriginal=r.GetGuid(1);baseLine=r.GetGuid(2);baseSource=r.GetGuid(3);}
  }
  Require(query!=null,"Actual repository query seam absent");string before=Fingerprint();
  Case("original package unit price and basis",(c,t)=>{using(var d=Read(c,t,false)){Require(d.Tables.Count==2&&d.Tables[0].Rows.Count==1&&d.Tables[1].Rows.Count==1,"Document shape");Require(Convert.ToString(d.Tables[1].Rows[0][7])=="شريط"&&Convert.ToDecimal(d.Tables[1].Rows[0][8])==100m&&Convert.ToInt32(d.Tables[1].Rows[0][9])==1,"Original package metadata");}});
  Case("base return retains indivisible original price basis",(c,t)=>{using(var d=Read(c,t,true)){Require(Convert.ToString(d.Tables[1].Rows[0][7])=="وحدة أساسية من عبوة ثلاثية"&&Convert.ToDecimal(d.Tables[1].Rows[0][8])==115m&&Convert.ToInt32(d.Tables[1].Rows[0][9])==3,"Original base metadata");}});
  Case("catalog changes do not recalculate saved unit",(c,t)=>{Exec(c,t,"UPDATE u SET BaseUnitsPerUnit=BaseUnitsPerUnit+7,SellingPrice=SellingPrice+99 FROM dbo.MedicineUnitsTb u JOIN dbo.MedicineUnitCatalogTb catalog ON catalog.CatalogId=u.CatalogId WHERE LEFT(catalog.MedName,12)=N'__UNIT_COMM_' AND u.UnitId<>catalog.BaseUnitId");using(var d=Read(c,t,false))Require(Convert.ToDecimal(d.Tables[1].Rows[0][8])==100m,"Catalog changed history");});
  Case("reject required package price mismatch",(c,t)=>{Exec(c,t,"UPDATE dbo.InvoiceUnitSnapshotsTb SET UnitPrice=UnitPrice+1,GrossTotal=ROUND(EnteredQuantity*(UnitPrice+1),2) WHERE DocumentKind=N'CommercialReturn' AND LineKey=CONVERT(nvarchar(100),@package)");Reject(c,t,false);});
  Case("reject required package currency mismatch",(c,t)=>{Exec(c,t,"UPDATE dbo.InvoiceUnitSnapshotsTb SET CurrencyCode=N'USD' WHERE DocumentKind=N'CommercialReturn' AND LineKey=CONVERT(nvarchar(100),@package)");Reject(c,t,false);});
  Case("reject missing required package snapshot",(c,t)=>{Exec(c,t,"DELETE dbo.InvoiceUnitSnapshotsTb WHERE DocumentKind=N'CommercialReturn' AND LineKey=CONVERT(nvarchar(100),@package)");Reject(c,t,false);});
  Case("reject missing required base sidecar",(c,t)=>{Exec(c,t,"DELETE dbo.CommercialReturnUnitSnapshotsTb WHERE ReturnInvoiceLineId=@base");Reject(c,t,true);});
  Case("reject base original price mismatch",(c,t)=>{Exec(c,t,"UPDATE dbo.CommercialReturnUnitSnapshotsTb SET OriginalUnitPrice=OriginalUnitPrice+1 WHERE ReturnInvoiceLineId=@base");Reject(c,t,true);});
  Case("reject matching snapshots in wrong invoice currency",(c,t)=>{Exec(c,t,"UPDATE dbo.CommercialReturnUnitSnapshotsTb SET CurrencyCode=N'USD' WHERE ReturnInvoiceLineId=@base; UPDATE dbo.InvoiceUnitSnapshotsTb SET CurrencyCode=N'USD' WHERE DocumentKind=N'CommercialSale' AND LineKey=CONVERT(nvarchar(100),@source)");Reject(c,t,true);});
  Case("corrupt unrelated document does not block requested base return",(c,t)=>{Exec(c,t,"DELETE dbo.InvoiceUnitSnapshotsTb WHERE DocumentKind=N'CommercialReturn' AND LineKey=CONVERT(nvarchar(100),@package)");using(var d=Read(c,t,true))Require(d.Tables[1].Rows.Count==1,"Unrelated corruption blocked valid requested document");});
  Case("reject absent required unit snapshot table",(c,t)=>{Exec(c,t,"EXEC sys.sp_rename N'dbo.InvoiceUnitSnapshotsTb',N'__ReturnHistoryRollbackUnits'");Reject(c,t,false);});
  Case("absent base table preserves package and rejects required base",(c,t)=>{Exec(c,t,"EXEC sys.sp_rename N'dbo.CommercialReturnUnitSnapshotsTb',N'__ReturnHistoryRollbackBase'");using(var d=Read(c,t,false))Require(d.Tables[1].Rows.Count==1,"Package branch blocked");Reject(c,t,true);});
  Require(before==Fingerprint(),"Rollback data fingerprint differs");Console.WriteLine("PASS identical before/after SHA256="+before+" for six complete table projections");Console.WriteLine("RESULT return-history matrix passed="+passed+" failed="+failed+"; all mutations rolled back; no UI, posting or physical printing");return failed==0?0:1;
 }catch(Exception error){Console.Error.WriteLine(error);return 2;}}
 static SqlConnection Open(){var c=new SqlConnection(cs);c.Open();return c;}
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Exec(SqlConnection c,SqlTransaction t,string sql){using(var cmd=new SqlCommand(sql,c,t)){cmd.CommandTimeout=10;cmd.Parameters.AddWithValue("@package",packageLine);cmd.Parameters.AddWithValue("@base",baseLine);cmd.Parameters.AddWithValue("@source",baseSource);cmd.ExecuteNonQuery();}}
 static DataSet Read(SqlConnection c,SqlTransaction t,bool basic){using(var cmd=new SqlCommand((string)query.Invoke(null,new object[]{basic?baseOriginal:packageOriginal,basic?baseReturn:packageReturn}),c,t)){cmd.CommandTimeout=10;cmd.Parameters.AddWithValue("@ReturnId",basic?baseReturn:packageReturn);cmd.Parameters.AddWithValue("@OriginalInvoiceId",basic?baseOriginal:packageOriginal);var result=new DataSet();try{using(var adapter=new SqlDataAdapter(cmd))adapter.Fill(result);return result;}catch{result.Dispose();throw;}}}
 static void Reject(SqlConnection c,SqlTransaction t,bool basic){try{using(var d=Read(c,t,basic)){} }catch(SqlException error){if(error.Number==51000)return;throw;}throw new Exception("Required invalid snapshot accepted");}
 static void Case(string name,Action<SqlConnection,SqlTransaction> action){try{using(var c=Open())using(var t=c.BeginTransaction()){try{action(c,t);}finally{if(t.Connection!=null)t.Rollback();}}passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static string Fingerprint(){string[] queries={"SELECT * FROM dbo.SalesInvoicesTb ORDER BY InvoiceId","SELECT * FROM dbo.SalesInvoiceLinesTb ORDER BY LineId","SELECT * FROM dbo.CommercialReturnLinesTb ORDER BY ReturnInvoiceLineId","SELECT * FROM dbo.InvoiceUnitSnapshotsTb ORDER BY DocumentKind,LineKey","SELECT * FROM dbo.CommercialReturnUnitSnapshotsTb ORDER BY ReturnInvoiceLineId","SELECT * FROM dbo.MedicineUnitsTb ORDER BY UnitId"};var text=new StringBuilder();using(var c=Open())foreach(string sql in queries){text.AppendLine(sql);using(var cmd=new SqlCommand(sql,c))using(var r=cmd.ExecuteReader())while(r.Read()){for(int i=0;i<r.FieldCount;i++){object v=r[i];string value=v is DateTime?((DateTime)v).ToString("O",CultureInfo.InvariantCulture):Convert.ToString(v,CultureInfo.InvariantCulture);text.Append(value.Length).Append(':').Append(value);}text.AppendLine();}}using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-","");}
}

}
